/* eslint-disable @next/next/no-img-element */
import imageManifest from "@/lib/responsive-images.generated.json";

interface VariantInfo {
  url: string;
  width: number;
  bytes: number;
}
interface ResponsiveImageInfo {
  width: number;
  height: number;
  originalBytes: number;
  srcSet: string;
  variants: VariantInfo[];
}
const images = imageManifest as Record<string, ResponsiveImageInfo | undefined>;

/**
 * Responsive static WebP images without /_next/image redirects.
 * Actual variants are generated by the Vite config plugin before builds
 * and recorded in a generated manifest. The original is always the fallback.
 */
export function ResponsiveImage({
  src, alt, sizes, priority = false,
}: {
  src: string;
  alt: string;
  sizes: string;
  priority?: boolean;
  fill?: boolean;
}) {
  const info = images[src];
  return (
    <img
      src={src}
      srcSet={info?.srcSet}
      sizes={info ? sizes : undefined}
      width={info?.width}
      height={info?.height}
      alt={alt}
      loading={priority ? "eager" : "lazy"}
      fetchPriority={priority ? "high" : undefined}
      decoding="async"
      style={{ position: "absolute", inset: 0, width: "100%", height: "100%" }}
    />
  );
}
